func ptBrief(t *strings.Builder, nodes *port.Cells, regions *port.Cells, text *port.Cells) int32 {
	// The brief of the Model (see the head of this file): every node but the root, in id order.
	var n int32 = model.NodeCount(nodes)
	var i int32 = 1
	var k int32 = 0
	var kind int32 = 0
	var s int32 = 0
	for i < n {
		kind = model.NodeKind(nodes, i)
		if kind == model.NkParagraph() {
			port.TextCp(t, 80)
			port.TextI32(t, model.NodeRegionCount(nodes, i))
			port.TextCp(t, 58)
		}
		if kind == model.NkText() {
			port.TextCp(t, 84)
			port.TextCp(t, 58)
		}
		if kind == model.NkNote() {
			port.TextCp(t, 78)
			port.TextI32(t, model.NodeSub(nodes, i))
		}
		if kind == model.NkBreak() {
			port.TextCp(t, 66)
			port.TextI32(t, model.NodeSub(nodes, i))
		}
		if (kind == model.NkParagraph()) || (kind == model.NkText()) {
			s = model.NodeTextStart(nodes, i)
			k = 0
			for k < model.NodeTextLen(nodes, i) {
				port.TextCp(t, model.TextAt(text, s+k))
				k += 1
			}
		}
		port.TextCp(t, 59)
		i += 1
	}
	return 0
}

func TestAGapAndAnIndentEndAParagraph(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var ord *port.Cells = port.NewCells()
	var raw *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var fr *port.Cells = port.NewCells()
	var gp *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	var t4 *strings.Builder = port.NewText()
	// A vertical gap above 1.5 times the median: five lines, a tight run of three, a jump, two.
	ptLine(wd, ln, et, port.TextBlob("alpha beta"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("gamma delta"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("epsilon"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("zeta eta"), 1, 7200, 15400, 50000, 16600, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("theta"), 1, 7200, 16900, 20000, 18100, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "gap: well formed")
	ptBrief(t1, nodes, regions, text)
	port.AssertText(emonT, t1, "P1:alpha beta gamma delta epsilon;P1:zeta eta theta;", "a gap of 12 pt after lines 3 pt apart starts a paragraph")
	// An indent: more than half the size, from a line at the margin. The first line of a paragraph is
	// indented, the rest are not: a LESS indented line goes on (a hanging or ordinary paragraph).
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("one two"), 1, 9600, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("three four"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("five"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("six seven"), 1, 9600, 14500, 50000, 15700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("eight"), 1, 7200, 16000, 20000, 17200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "indent: well formed")
	ptBrief(t2, nodes, regions, text)
	port.AssertText(emonT, t2, "P1:one two three four five;P1:six seven eight;", "an indented line after one at the margin starts a paragraph")
	// Centred lines start anywhere: a line that does not start at the page's margin is not an indent. The
	// first line is at the margin (and ends the first paragraph with its gap), the three centred lines go on.
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("left"), 1, 7200, 10000, 20000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("mid a"), 1, 9000, 13000, 40000, 14200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("mid bb"), 1, 11000, 14500, 38000, 15700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("mid c"), 1, 10000, 16000, 39000, 17200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "centred: well formed")
	ptBrief(t3, nodes, regions, text)
	port.AssertText(emonT, t3, "P1:left;P1:mid a mid bb mid c;", "centred lines are one paragraph")
	// Lines on one row (two columns, a table row) do not follow one another: the second is not below the first.
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("left col"), 1, 7200, 10000, 25000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("right col"), 1, 30000, 10000, 50000, 11200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "row: well formed")
	ptBrief(t4, nodes, regions, text)
	port.AssertText(emonT, t4, "P1:left col;P1:right col;", "two lines on one row are two paragraphs")
}

func TestLinesAreReadTopToBottomWhateverOrderTheyWerePainted(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var ord *port.Cells = port.NewCells()
	var raw *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var fr *port.Cells = port.NewCells()
	var gp *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	// Painted last line first and the first line in the middle (a float is painted before the page's text).
	ptLine(wd, ln, et, port.TextBlob("three"), 1, 7200, 13000, 30000, 14200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("one"), 1, 7200, 10000, 30000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("two"), 1, 7200, 11500, 30000, 12700, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "order: well formed")
	ptBrief(t1, nodes, regions, text)
	port.AssertText(emonT, t1, "P1:one two three;", "the reading order is the page's, not the painting's")
	// A rotated line is not in the column of upright ones: it stands alone, after them (a watermark
	// across the middle of a paragraph does not cut it), and does not stop the paragraph that goes on.
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("first line"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("DRAFT"), 1, 20000, 11000, 30000, 12500, 4500, 0, 3000)
	ptLine(wd, ln, et, port.TextBlob("second line"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 1, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "rotated: well formed")
	ptBrief(t2, nodes, regions, text)
	port.AssertText(emonT, t2, "P1:first line second line;P1:DRAFT;", "a rotated line stands alone, after the upright ones")
}

