func ptGolden(pdf []byte, t *strings.Builder, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, pages *port.Cells, ledger *port.Cells, layout *port.Cells, ord *port.Cells, raw *port.Cells, tmp *port.Cells, fr *port.Cells, gp *port.Cells, mst *port.Cells) int32 {
	// PDF -> content -> paragraphs -> Model -> pretty JSON; answer 0 when every step answered 0, else a
	// code naming the step (1 open, 2 content, 3 the Model's check). The JSON is `t`.
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(mk, 0)
	port.CellsDrop(fnt, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	var src *port.Src = port.SrcOfBlob(pdf)
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	if o != 0 {
		return 1
	}
	if pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0 {
		return 2
	}
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	para.PaPages(pg, pages)
	var np int32 = port.CellsLen(pages) / 16
	var sf *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var hc *port.Cells = port.NewCells()
	var ws *port.Cells = port.NewCells()
	var htmp *port.Cells = port.NewCells()
	var hpr *port.Cells = port.NewCells()
	var hptxt *port.Cells = port.NewCells()
	var lt *port.Cells = port.NewCells()
	var ii *port.Cells = port.NewCells()
	ptPrep(wd, ln, et, np, gl, fnt, lt, ii)
	heading.HdAnalyze(wd, lt, et, gl, sf, sc, hc, ws, htmp, hpr, hptxt)
	ptBuild(wd, et, np, pages, layout, nodes, attrs, regions, text, ord, raw, tmp, fr, gp, hc, lt, ii)
	if model.ModelCheck(nodes, attrs, regions, text, pages, ledger, layout, mst) != 0 {
		return 3
	}
	json.JsEmit(t, 1, nodes, attrs, regions, text, pages, ledger, layout)
	return 0
}

